pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address other) internal {
        vm.assume(other != address(this));
        address initial;
        try c.owner() returns (address __r) { initial = __r; } catch { return; }
        vm.assume(initial == address(this));
        bool r1 = true;
        try c.setOwner(other) { r1 = true; } catch { r1 = false; }
        bool r2 = true;
        try c.setOwner(initial) { r2 = true; } catch { r2 = false; }
        assertTrue(r1 && r2 && c.owner() == initial);
    }

    function testFuzz_run(address other) public {
        vm.assume(other.code.length == 0 && uint160(other) > 0xffff && other != address(this) && other != address(c) && other != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && other != 0x000000000000000000636F6e736F6c652e6c6f67 && other != 0x4e59b44847b379578588920cA78FbF26c0B4956C && other != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(other);
